-- Test-only compatibility baseline extracted from principal project's catalogs on 2026-11-11.
-- No customer rows. Existing CRM base schema is absent from tracked migrations.
-- Only tables needed by this suite; unrelated triggers/FKs deliberately omitted.
do $$begin
  if not exists(select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
  if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
  if not exists(select 1 from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if;
end$$;
create schema auth;
create schema private;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid$$;
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
create table private.user_active_tenants(user_id uuid primary key,tenant_id uuid not null);
create table private.crm_client_portal_locks(user_id uuid,tenant_id uuid,auth_session_id uuid);
create table public.platform_users(user_id uuid,platform_role text,status text);

create table public.audit_logs (
  id bigint generated by default as identity,
  tenant_id uuid,
  actor_user_id uuid,
  action text not null,
  entity_type text,
  entity_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamp with time zone not null default now(),
  constraint audit_logs_pkey PRIMARY KEY (id)
);

create table public.companies (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  name text not null,
  domain text,
  email text,
  phone text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  website text,
  instagram_url text,
  whatsapp_phone text,
  city text,
  sector text,
  constraint companies_pkey PRIMARY KEY (id),
  constraint companies_tenant_id_id_key UNIQUE (tenant_id, id)
);

create table public.contacts (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  company_id uuid,
  first_name text,
  last_name text,
  display_name text not null,
  email text,
  phone text,
  source text,
  status text not null default 'lead'::text,
  owner_user_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  job_title text,
  whatsapp_phone text,
  constraint contacts_pkey PRIMARY KEY (id),
  constraint contacts_status_check CHECK ((status = ANY (ARRAY['lead'::text, 'prospect'::text, 'customer'::text, 'inactive'::text]))),
  constraint contacts_tenant_id_id_key UNIQUE (tenant_id, id)
);

create table public.customer_payments (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  order_id uuid not null,
  amount numeric not null,
  currency text not null default 'DOP'::text,
  payment_method text,
  status text not null default 'recorded'::text,
  reference text,
  evidence_url text,
  received_at timestamp with time zone not null default now(),
  recorded_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  constraint customer_payments_amount_check CHECK ((amount > (0)::numeric)),
  constraint customer_payments_pkey PRIMARY KEY (id),
  constraint customer_payments_status_check CHECK ((status = ANY (ARRAY['recorded'::text, 'confirmed'::text, 'voided'::text]))),
  constraint customer_payments_tenant_id_id_key UNIQUE (tenant_id, id)
);

create table public.deliveries (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  order_id uuid not null,
  status text not null default 'pending'::text,
  delivery_zone text,
  delivery_address text,
  contact_name text,
  contact_phone text,
  responsible_user_id uuid,
  scheduled_at timestamp with time zone,
  delivered_at timestamp with time zone,
  shipping_cost numeric,
  evidence_url text,
  incident_notes text,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint deliveries_pkey PRIMARY KEY (id),
  constraint deliveries_shipping_cost_check CHECK (((shipping_cost IS NULL) OR (shipping_cost >= (0)::numeric))),
  constraint deliveries_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'scheduled'::text, 'out_for_delivery'::text, 'delivered'::text, 'incident'::text, 'cancelled'::text]))),
  constraint deliveries_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint deliveries_tenant_id_order_id_key UNIQUE (tenant_id, order_id)
);

create table public.inventory_items (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  sku text not null,
  name text not null,
  item_type text not null default 'blank'::text,
  unit text not null default 'unit'::text,
  on_hand numeric not null default 0,
  reserved numeric not null default 0,
  reorder_level numeric not null default 0,
  cost_per_unit numeric,
  supplier text,
  active boolean not null default true,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint inventory_items_check CHECK (((reserved >= (0)::numeric) AND (reserved <= on_hand))),
  constraint inventory_items_cost_per_unit_check CHECK (((cost_per_unit IS NULL) OR (cost_per_unit >= (0)::numeric))),
  constraint inventory_items_item_type_check CHECK ((item_type = ANY (ARRAY['blank'::text, 'material'::text, 'packaging'::text, 'consumable'::text, 'other'::text]))),
  constraint inventory_items_on_hand_check CHECK ((on_hand >= (0)::numeric)),
  constraint inventory_items_pkey PRIMARY KEY (id),
  constraint inventory_items_reorder_level_check CHECK ((reorder_level >= (0)::numeric)),
  constraint inventory_items_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint inventory_items_tenant_id_sku_key UNIQUE (tenant_id, sku)
);

create table public.inventory_movements (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  inventory_item_id uuid not null,
  order_id uuid,
  movement_type text not null,
  quantity numeric not null,
  unit_cost numeric,
  idempotency_key text not null,
  notes text,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  constraint inventory_movements_movement_type_check CHECK ((movement_type = ANY (ARRAY['entry'::text, 'exit'::text, 'adjustment'::text, 'reserve'::text, 'release'::text, 'consume'::text]))),
  constraint inventory_movements_pkey PRIMARY KEY (id),
  constraint inventory_movements_quantity_check CHECK ((quantity > (0)::numeric)),
  constraint inventory_movements_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint inventory_movements_tenant_id_idempotency_key_key UNIQUE (tenant_id, idempotency_key),
  constraint inventory_movements_unit_cost_check CHECK (((unit_cost IS NULL) OR (unit_cost >= (0)::numeric)))
);

create table public.memberships (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  user_id uuid not null,
  role text not null default 'agent'::text,
  status text not null default 'active'::text,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint memberships_pkey PRIMARY KEY (id),
  constraint memberships_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text, 'agent'::text, 'viewer'::text]))),
  constraint memberships_status_check CHECK ((status = ANY (ARRAY['active'::text, 'invited'::text, 'suspended'::text]))),
  constraint memberships_tenant_id_user_id_key UNIQUE (tenant_id, user_id)
);

create table public.opportunities (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  pipeline_id uuid not null,
  stage_id uuid not null,
  contact_id uuid,
  company_id uuid,
  title text not null,
  value numeric(14,2) not null default 0,
  currency text not null default 'DOP'::text,
  probability numeric(5,4) not null default 0,
  status text not null default 'open'::text,
  expected_close_date date,
  owner_user_id uuid,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  setup_value numeric not null default 0,
  mrr_value numeric not null default 0,
  total_contract_value numeric not null default 0,
  actual_close_date date,
  acquisition_source text,
  offer text,
  loss_reason text,
  lead_score integer not null default 0,
  next_action text,
  next_action_at timestamp with time zone,
  last_activity_at timestamp with time zone,
  setup_collected numeric not null default 0,
  recurring_cash_collected numeric not null default 0,
  metadata jsonb not null default '{}'::jsonb,
  constraint opportunities_lead_score_check CHECK (((lead_score >= 0) AND (lead_score <= 100))),
  constraint opportunities_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  constraint opportunities_mrr_value_check CHECK ((mrr_value >= (0)::numeric)),
  constraint opportunities_pkey PRIMARY KEY (id),
  constraint opportunities_probability_check CHECK (((probability >= (0)::numeric) AND (probability <= (1)::numeric))),
  constraint opportunities_recurring_cash_collected_check CHECK ((recurring_cash_collected >= (0)::numeric)),
  constraint opportunities_setup_collected_check CHECK ((setup_collected >= (0)::numeric)),
  constraint opportunities_setup_value_check CHECK ((setup_value >= (0)::numeric)),
  constraint opportunities_status_check CHECK ((status = ANY (ARRAY['open'::text, 'won'::text, 'lost'::text]))),
  constraint opportunities_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint opportunities_total_contract_value_check CHECK ((total_contract_value >= (0)::numeric)),
  constraint opportunities_value_check CHECK ((value >= (0)::numeric))
);

create table public.order_items (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
