  constraint order_items_line_total_check CHECK ((line_total >= (0)::numeric)),
  constraint order_items_pkey PRIMARY KEY (id),
  constraint order_items_quantity_check CHECK ((quantity > (0)::numeric)),
  constraint order_items_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint order_items_unit_price_check CHECK ((unit_price >= (0)::numeric))
);

create table public.orders (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  order_number text not null,
  quotation_id uuid,
  contact_id uuid,
  company_id uuid,
  opportunity_id uuid,
  status text not null default 'confirmed'::text,
  currency text not null default 'DOP'::text,
  subtotal numeric not null default 0,
  discount_total numeric not null default 0,
  tax_total numeric not null default 0,
  total numeric not null default 0,
  amount_paid numeric not null default 0,
  notes text,
  requested_at timestamp with time zone,
  committed_at timestamp with time zone,
  confirmed_at timestamp with time zone default now(),
  delivered_at timestamp with time zone,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint orders_amount_paid_check CHECK ((amount_paid >= (0)::numeric)),
  constraint orders_discount_total_check CHECK ((discount_total >= (0)::numeric)),
  constraint orders_pkey PRIMARY KEY (id),
  constraint orders_status_check CHECK ((status = ANY (ARRAY['confirmed'::text, 'in_production'::text, 'quality_control'::text, 'ready_for_delivery'::text, 'out_for_delivery'::text, 'delivered'::text, 'on_hold'::text, 'cancelled'::text]))),
  constraint orders_subtotal_check CHECK ((subtotal >= (0)::numeric)),
  constraint orders_tax_total_check CHECK ((tax_total >= (0)::numeric)),
  constraint orders_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint orders_tenant_id_order_number_key UNIQUE (tenant_id, order_number),
  constraint orders_total_check CHECK ((total >= (0)::numeric))
);

create table public.production_jobs (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  order_id uuid not null,
  status text not null default 'queued'::text,
  priority integer not null default 3,
  technique text,
  design_file_url text,
  design_approved boolean not null default false,
  design_approved_at timestamp with time zone,
  assigned_to uuid,
  materials_required jsonb not null default '[]'::jsonb,
  requested_at timestamp with time zone,
  committed_at timestamp with time zone,
  started_at timestamp with time zone,
  completed_at timestamp with time zone,
  quality_control_status text,
  incident_notes text,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint production_jobs_pkey PRIMARY KEY (id),
  constraint production_jobs_priority_check CHECK (((priority >= 1) AND (priority <= 5))),
  constraint production_jobs_quality_control_status_check CHECK (((quality_control_status IS NULL) OR (quality_control_status = ANY (ARRAY['pending'::text, 'passed'::text, 'failed'::text])))),
  constraint production_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'blocked_design_approval'::text, 'ready'::text, 'in_progress'::text, 'quality_control'::text, 'completed'::text, 'incident'::text, 'cancelled'::text]))),
  constraint production_jobs_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint production_jobs_tenant_id_order_id_key UNIQUE (tenant_id, order_id),
  constraint production_requires_design_approval CHECK (((status <> ALL (ARRAY['ready'::text, 'in_progress'::text, 'quality_control'::text, 'completed'::text])) OR (design_approved = true)))
);

create table public.products (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  sku text not null,
  name text not null,
  description text,
  status text not null default 'active'::text,
  source_system text not null default 'crm'::text,
  sale_price numeric(14,2) not null default 0,
  currency text not null default 'DOP'::text,
  tax_rate numeric(7,4) not null default 0,
  stock_snapshot numeric(14,3),
  stock_synced_at timestamp with time zone,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint products_pkey PRIMARY KEY (id),
  constraint products_sale_price_check CHECK ((sale_price >= (0)::numeric)),
  constraint products_source_system_check CHECK ((source_system = ANY (ARRAY['crm'::text, 'odoo'::text]))),
  constraint products_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'archived'::text]))),
  constraint products_tax_rate_check CHECK (((tax_rate >= (0)::numeric) AND (tax_rate <= (100)::numeric))),
  constraint products_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint products_tenant_id_sku_key UNIQUE (tenant_id, sku)
);

create table public.quotation_items (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  quotation_id uuid not null,
  product_id uuid,
  "position" integer not null default 0,
  sku_snapshot text,
  description text not null,
  quantity numeric(14,3) not null default 1,
  unit_price numeric(14,2) not null default 0,
  discount_percent numeric(7,4) not null default 0,
  tax_rate numeric(7,4) not null default 0,
  line_subtotal numeric(14,2) generated always as (round(((quantity * unit_price) * ((1)::numeric - (discount_percent / 100.0))), 2)) stored,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint quotation_items_discount_percent_check CHECK (((discount_percent >= (0)::numeric) AND (discount_percent <= (100)::numeric))),
  constraint quotation_items_pkey PRIMARY KEY (id),
  constraint quotation_items_quantity_check CHECK ((quantity > (0)::numeric)),
  constraint quotation_items_quotation_id_position_key UNIQUE (quotation_id, "position"),
  constraint quotation_items_tax_rate_check CHECK (((tax_rate >= (0)::numeric) AND (tax_rate <= (100)::numeric))),
  constraint quotation_items_unit_price_check CHECK ((unit_price >= (0)::numeric))
);

create table public.quotations (
  id uuid not null default gen_random_uuid(),
  tenant_id uuid not null,
  quote_number text not null,
  contact_id uuid,
  company_id uuid,
  opportunity_id uuid,
  status text not null default 'draft'::text,
  currency text not null default 'DOP'::text,
  valid_until date,
  notes text,
  terms text,
  subtotal numeric(14,2) not null default 0,
  discount_total numeric(14,2) not null default 0,
  tax_total numeric(14,2) not null default 0,
  total numeric(14,2) not null default 0,
  accepted_at timestamp with time zone,
  rejected_at timestamp with time zone,
  erp_order_status text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid default auth.uid(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint quotations_discount_total_check CHECK ((discount_total >= (0)::numeric)),
  constraint quotations_pkey PRIMARY KEY (id),
  constraint quotations_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'accepted'::text, 'rejected'::text, 'expired'::text, 'cancelled'::text]))),
  constraint quotations_subtotal_check CHECK ((subtotal >= (0)::numeric)),
  constraint quotations_tax_total_check CHECK ((tax_total >= (0)::numeric)),
  constraint quotations_tenant_id_id_key UNIQUE (tenant_id, id),
  constraint quotations_tenant_id_quote_number_key UNIQUE (tenant_id, quote_number),
  constraint quotations_total_check CHECK ((total >= (0)::numeric))
);

create table public.tenants (
  id uuid not null default gen_random_uuid(),
  name text not null,
  slug text not null,
  status text not null default 'active'::text,
  owner_user_id uuid not null,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  constraint tenants_pkey PRIMARY KEY (id),
  constraint tenants_slug_format CHECK ((slug ~ '^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$'::text)),
  constraint tenants_slug_key UNIQUE (slug),
  constraint tenants_status_check CHECK ((status = ANY (ARRAY['active'::text, 'trial'::text, 'suspended'::text, 'cancelled'::text])))
);
CREATE OR REPLACE FUNCTION private.crm_is_client_portal_locked()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists(select 1 from private.crm_client_portal_locks l
    where l.user_id=auth.uid()
      and l.auth_session_id=case
        when (auth.jwt()->>'session_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then (auth.jwt()->>'session_id')::uuid else null end);
$function$;

CREATE OR REPLACE FUNCTION private.crm_is_platform_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select not private.crm_is_client_portal_locked()
   and exists(select 1 from public.platform_users pu
     where pu.user_id=(select auth.uid()) and pu.status='active'
       and pu.platform_role in ('platform_owner','platform_admin'));
$function$;

CREATE OR REPLACE FUNCTION private.is_platform_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.crm_is_platform_admin();
$function$;

CREATE OR REPLACE FUNCTION private.platform_client_view_tenant()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select l.tenant_id from private.crm_client_portal_locks l
  where l.user_id=(select auth.uid())
    and l.auth_session_id=case
     when (auth.jwt()->>'session_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       then (auth.jwt()->>'session_id')::uuid else null end
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION private.crm_tenant_is_operational(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select exists(select 1 from public.tenants t where t.id=p_tenant_id and t.status in ('active','trial')); $function$;

CREATE OR REPLACE FUNCTION private.has_tenant_role(p_tenant_id uuid, p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select (private.platform_client_view_tenant() is null
   or private.platform_client_view_tenant()=p_tenant_id)
  and (private.is_platform_admin()
       or (private.crm_tenant_is_operational(p_tenant_id)
         and exists(select 1 from public.memberships m
           where m.tenant_id=p_tenant_id and m.user_id=(select auth.uid())
             and m.status='active' and m.role=any(p_roles))));
$function$;

CREATE OR REPLACE FUNCTION private.has_tenant_access(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select (private.platform_client_view_tenant() is null
   or private.platform_client_view_tenant()=p_tenant_id)
  and (private.is_platform_admin()
       or (private.crm_tenant_is_operational(p_tenant_id)
         and exists(select 1 from public.memberships m
           where m.tenant_id=p_tenant_id and m.user_id=(select auth.uid()) and m.status='active')));
$function$;

CREATE OR REPLACE FUNCTION private.can_operate_crm(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ select private.has_tenant_role(p_tenant_id, array['owner','admin','manager','agent']::text[]); $function$;

CREATE OR REPLACE FUNCTION private.can_manage_crm(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ select private.has_tenant_role(p_tenant_id, array['owner','admin','manager']::text[]); $function$;

CREATE OR REPLACE FUNCTION private.crm_active_tenant_matches(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    (
      select uat.tenant_id = p_tenant_id
      from private.user_active_tenants uat
      where uat.user_id = auth.uid()
    ),
    true
  )
$function$;

CREATE OR REPLACE FUNCTION private.is_tenant_admin(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select private.has_tenant_role(p_tenant_id,array['owner','admin']::text[]); $function$;

alter table public.customer_payments enable row level security;
alter table public.inventory_items enable row level security;
alter table public.inventory_movements enable row level security;
alter table public.order_items enable row level security;
alter table public.orders enable row level security;
alter table public.products enable row level security;
alter table public.quotation_items enable row level security;
alter table public.quotations enable row level security;
create policy customer_payments_delete on public.customer_payments for DELETE to authenticated using (private.can_manage_crm(tenant_id));
create policy customer_payments_insert on public.customer_payments for INSERT to authenticated with check (private.can_operate_crm(tenant_id));
create policy customer_payments_select on public.customer_payments for SELECT to authenticated using (private.has_tenant_access(tenant_id));
create policy customer_payments_update on public.customer_payments for UPDATE to authenticated using (private.can_operate_crm(tenant_id)) with check (private.can_operate_crm(tenant_id));
